import{_ as d,o as r,c as e,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"写作证据卡：从工具润色到署名交付","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/writing-evidence.zh.md","filePath":"public/downloads/worksheets/writing-evidence.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/writing-evidence.zh.md"};function i(l,t,b,n,o,s){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="写作证据卡-从工具润色到署名交付" tabindex="-1">写作证据卡：从工具润色到署名交付 <a class="header-anchor" href="#写作证据卡-从工具润色到署名交付" aria-label="Permalink to &quot;写作证据卡：从工具润色到署名交付&quot;">​</a></h1><p>把这张卡复制到私有笔记中，一次只记录一个真实写作任务。不要写入密码、客户资料、未获许可的第三方信息、考试答案或不必要的隐私。最终版本可以公开，不代表原始初稿、反馈和工具记录必须公开。</p><h2 id="_1-定义任务、读者与责任" tabindex="-1">1. 定义任务、读者与责任 <a class="header-anchor" href="#_1-定义任务、读者与责任" aria-label="Permalink to &quot;1. 定义任务、读者与责任&quot;">​</a></h2><h3 id="writing-evidence-yyyy-mm-dd" tabindex="-1">Writing Evidence - YYYY-MM-DD <a class="header-anchor" href="#writing-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Writing Evidence - YYYY-MM-DD&quot;">​</a></h3><p>真实场景：<br> 任务：说明 / 请求 / 状态更新 / 决策 / 叙事 / 反思 / 交接<br> 受众与关系：<br> 读完后对方需要理解、决定或做什么：<br> 体裁、字数与截止时间：<br> 完成标准：<br> 允许的词典 / 翻译 / 搜索 / AI / 人工帮助：<br> 保密、版权、隐私与署名边界：<br> 最终责任人：</p><p>若机构、学校、客户或招聘流程禁止某类帮助，以当前规则为准。</p><h2 id="_2-保存无辅助初稿" tabindex="-1">2. 保存无辅助初稿 <a class="header-anchor" href="#_2-保存无辅助初稿" aria-label="Permalink to &quot;2. 保存无辅助初稿&quot;">​</a></h2><p>原始初稿位置：<br> 首版用时与字数：<br> 首版允许的提纲或资料：<br> 我想让读者记住的一句话：<br> 我最没有把握的事实：<br> 最可能被漂亮话掩盖的空缺：<br> 我根据首版期待读者采取的行动：</p><p>不先查整句译文、不让 AI 生成正文。保留停顿、重复和失败段落；它们是以后比较的基线。</p><h2 id="_3-建立事实与责任账本" tabindex="-1">3. 建立事实与责任账本 <a class="header-anchor" href="#_3-建立事实与责任账本" aria-label="Permalink to &quot;3. 建立事实与责任账本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主张/内容</th><th>类型</th><th>来源、版本与位置</th><th>核验日期</th><th>置信度</th><th>可否公开</th><th>什么会改变它</th></tr></thead><tbody><tr><td></td><td>事实 / 数字 / 引语 / 经历 / 推断 / 建议 / 他人信息</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>当时知道什么、后来才知道什么：<br> 需要许可的第三方内容：<br> 仍然无法核验的部分：<br> 必须在交付前删除或匿名化的内容：</p><h2 id="_4-保存文档骨架" tabindex="-1">4. 保存文档骨架 <a class="header-anchor" href="#_4-保存文档骨架" aria-label="Permalink to &quot;4. 保存文档骨架&quot;">​</a></h2><p>读者面对的问题：<br> 直接回答：<br> 依据 1：<br> 依据 2：<br> 具体例子/最小事实：<br> 限制、反例或未知：<br> 读者下一步：</p><table tabindex="0"><thead><tr><th>段落</th><th>功能</th><th>必须保留</th><th>可以删除/移动</th><th>理由</th></tr></thead><tbody><tr><td></td><td>背景 / 问题 / 主张 / 理由 / 证据 / 例子 / 转折 / 限制 / 请求 / 决定 / 交接</td><td></td><td></td><td></td></tr></tbody></table><h2 id="_5-记录翻译的意义变化" tabindex="-1">5. 记录翻译的意义变化 <a class="header-anchor" href="#_5-记录翻译的意义变化" aria-label="Permalink to &quot;5. 记录翻译的意义变化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我真正想表达</th><th>英文首版</th><th>翻译/工具候选</th><th>最终决定</th><th>理由</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>主体或责任是否改变：<br> 确定性是否被放大/减弱：<br> 否定或条件范围是否变化：<br> 语气是否适合关系：<br> 不可直译的术语/制度/文化概念：<br> 术语表与审校者：</p><p>自然、流畅和忠实是不同判断。最终作者需要解释取舍。</p><h2 id="_6-完成五次修订" tabindex="-1">6. 完成五次修订 <a class="header-anchor" href="#_6-完成五次修订" aria-label="Permalink to &quot;6. 完成五次修订&quot;">​</a></h2><table tabindex="0"><thead><tr><th>遍次</th><th>主要问题</th><th>修改前</th><th>修改后</th><th>为什么改变任务结果</th></tr></thead><tbody><tr><td>任务与事实</td><td></td><td></td><td></td><td></td></tr><tr><td>结构与证据</td><td></td><td></td><td></td><td></td></tr><tr><td>句子与意义</td><td></td><td></td><td></td><td></td></tr><tr><td>语域与声音</td><td></td><td></td><td></td><td></td></tr><tr><td>交付与边界</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>本轮必要纠错：<br> 歧义修复：<br> 语域选择：<br> 保留的个人风格：<br> 无法解释、因此没有接受的修改：</p><h2 id="_7-记录反馈吸收" tabindex="-1">7. 记录反馈吸收 <a class="header-anchor" href="#_7-记录反馈吸收" aria-label="Permalink to &quot;7. 记录反馈吸收&quot;">​</a></h2><p>先请读者复述，再看批注：</p><p>读者复述的主旨：<br> 读者认为的依据与限制：<br> 读者理解的下一步：<br> 需要猜测的位置：</p><table tabindex="0"><thead><tr><th>反馈</th><th>来源/关系</th><th>分类</th><th>决定</th><th>理由</th><th>是否进入平行文本</th></tr></thead><tbody><tr><td></td><td>真实读者 / 同伴 / 教师 / 编辑 / AI</td><td>纠错 / 歧义 / 结构 / 证据 / 语域 / 风格</td><td>采纳 / 部分 / 拒绝 / 延后</td><td></td><td></td></tr></tbody></table><p>旧稿改好不等于新任务会用。反馈必须进入一份平行文本才开始证明迁移。</p><h2 id="_8-记录-ai-与自动工具使用" tabindex="-1">8. 记录 AI 与自动工具使用 <a class="header-anchor" href="#_8-记录-ai-与自动工具使用" aria-label="Permalink to &quot;8. 记录 AI 与自动工具使用&quot;">​</a></h2><p>工具 / 模型 / 版本与日期：<br> 使用前已有的初稿与来源：<br> 请求：诊断 / 模拟读者 / 事实候选 / 语言纠错 / 版本比较 / 反例 / 其他<br> 模型生成或重写的范围：<br> 模型可能编造的事实、引语或来源：<br> 我逐项核验的方式：<br> 我采纳 / 拒绝什么，为什么：<br> 需要向学校、客户、雇主或读者披露什么：<br> 关闭工具后的平行任务：</p><p>模型输出可以成为候选，不拥有署名，也不能替最终作者承担责任。</p><h2 id="_9-检查异步交付" tabindex="-1">9. 检查异步交付 <a class="header-anchor" href="#_9-检查异步交付" aria-label="Permalink to &quot;9. 检查异步交付&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>内容</th><th>验收</th></tr></thead><tbody><tr><td>一句结论/主题行</td><td></td><td></td></tr><tr><td>已完成与证据位置</td><td></td><td></td></tr><tr><td>风险、阻塞与未知</td><td></td><td></td></tr><tr><td>需要谁何时决定什么</td><td></td><td></td></tr><tr><td>下一步、负责人和检查点</td><td></td><td></td></tr><tr><td>无回应时的处理</td><td></td><td></td></tr><tr><td>失败、停止与回滚</td><td></td><td></td></tr><tr><td>链接、附件与权限</td><td></td><td></td></tr></tbody></table><p>读者能否不参加额外会议就继续：<br> 真实回应或执行结果：<br> 交接后仍需作者口头补充的缺口：</p><h2 id="_10-做延迟保持与迁移" tabindex="-1">10. 做延迟保持与迁移 <a class="header-anchor" href="#_10-做延迟保持与迁移" aria-label="Permalink to &quot;10. 做延迟保持与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>撤掉什么</th><th>改变的条件</th><th>输出</th><th>结果</th></tr></thead><tbody><tr><td>第 1 天</td><td>不使用 AI 正文</td><td>原任务</td><td>初稿与交付版</td><td></td></tr><tr><td>第 3-7 天</td><td>撤掉旧句子和批注</td><td>新主题、同体裁</td><td>平行文本</td><td></td></tr><tr><td>第 14 天</td><td>撤掉最近反馈与翻译</td><td>新受众、同信息</td><td>语域迁移文本</td><td></td></tr><tr><td>第 30 天</td><td>关闭全部练习提示</td><td>真实邮件、报告、申请或交接</td><td>完整交付</td><td></td></tr></tbody></table><p>七天后仍能调用的结构与判断：<br> 换主题后再次出现的问题：<br> 是否减少整句翻译或全文重写依赖：<br> 读者是否更少猜测：<br> 下一轮只改变的变量：</p><h2 id="_11-评分与署名决定" tabindex="-1">11. 评分与署名决定 <a class="header-anchor" href="#_11-评分与署名决定" aria-label="Permalink to &quot;11. 评分与署名决定&quot;">​</a></h2><p>每项 0-2：<code>0=未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">第 1 天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>独立留下初稿</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>任务、读者和下一步清楚</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>事实、来源与推断可区分</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>结构和证据支持结论</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能解释翻译/AI/反馈修改</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>异步读者能继续或回滚</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>换主题、受众或体裁后仍能交付</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>当前版本：愿意署名 / 需再核验 / 需缩小范围 / 不应交付<br> 最重要的依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/6-writing" target="_blank" rel="noreferrer">写作篇：从初稿到可验证修订</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/grammar" target="_blank" rel="noreferrer">语法篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/4-reading" target="_blank" rel="noreferrer">阅读篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/7-ai" target="_blank" rel="noreferrer">用 AI 学英语</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">求职英语篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-3/4-artifacts-and-delivery" target="_blank" rel="noreferrer">作品篇</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/writing-evidence" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',43)])])}const c=d(h,[["render",i]]);export{p as __pageData,c as default};
